        ImpactScaleOnePct,
        LongOiCapUsd,
        ShortOiCapUsd,
        MaxNotionalUsd,
        PayoutCapX,
        MaxLeverage,
        BreakerBps,
        BreakerFloorUsdc,
        FeeBps,
        StakerFeeShareBps,
        MinDelay,
        Grace,
        Expiry,
        MaxJumpBps,
